class Solution { fun splitArraySameAverage(nums:IntArray):Boolean{val n=nums.size;val total=nums.sum();val sums=List(n/2+1){mutableSetOf<Int>()};sums[0].add(0);var used=0;for(value in nums){used++;for(count in minOf(used,n/2) downTo 1)for(previous in sums[count-1].toList())sums[count].add(previous+value)};for(count in 1..n/2)if(total*count%n==0&&total*count/n in sums[count])return true;return false} }
